// nodes loads the requested edges onto `rows`, which the caller already has: one
// query per edge, however many rows there are.
pub fn (q TagQuery) nodes(rows []models.Tag) ![]TagNode {
	mut nodes := rows.map(TagNode{
		graph: q.graph
		tag:   it
	})
	if q.with_articles {
		found := q.load_articles(rows, q.articles_fns)!
		for mut node in nodes {
			node.articles = found[node.tag.id.str()] or { [] }
			node.loaded << 'articles'
		}
	}
	for name, fns in q.named_articles {
		found := q.load_articles(rows, fns)!
		for mut node in nodes {
			node.named_articles[name] = found[node.tag.id.str()] or { [] }
		}
	}
	return nodes
}

// load_articles loads the `articles` of `rows`, keyed by each row's key.
fn (q TagQuery) load_articles(rows []models.Tag, fns []fn (ArticleQuery) ArticleQuery) !map[string][]ArticleNode {
	mut sub := q.graph.articles()
	for configure in fns {
		sub = configure(sub)
	}
	if sub.query.limit > 0 || sub.query.offset > 0 {
		prepared := q.graph.client.prepare_edge_query('articles', sub.query)!
		cut := load.link_each(q.graph.client.conn, 'article_tags', 'tag_id', 'article_id',
			rows.map(it.id.str()), .int, .i64, 'articles', 'id', load.Query{
				...prepared
				conds: prepared.conds
			})!
		// the targets by key: the join rows give their order
		found := sub.nodes(load.select_in[models.Article](q.graph.client.conn, 'id',
			load.unique(cut.map(it[1])),
			query: load.Query{ ...prepared, order: '', desc: false, orders: []load.Order{}, limit: 0, offset: 0 }
		)!)!
		mut by_key := map[string]ArticleNode{}
		for target in found {
			by_key[target.article.id.str()] = target
		}
		mut cut_linked := map[string][]ArticleNode{}
		for pair in cut {
			if target := by_key[pair[1]] {
				cut_linked[pair[0]] << target
			}
		}
		return cut_linked
	}
	pairs := load.link_pairs(q.graph.client.conn, 'article_tags', 'tag_id',
		'article_id', rows.map(it.id.str()), .int, .i64)!
	// each parent's targets in the order of the query: one select per group of
	// parents, so each parent's order comes from one statement
	mut linked := map[string][]ArticleNode{}
	for group in load.parent_groups(pairs) {
		targets := sub.nodes(load.select_in[models.Article](q.graph.client.conn, 'id',
			load.unique(group.map(it[1])),
			query: q.graph.client.prepare_edge_query('articles', sub.query)!
		)!)!
		mut parents_of := map[string][]string{}
		for pair in group {
			parents_of[pair[1]] << pair[0]
		}
		for target in targets {
			for parent in parents_of[target.article.id.str()] or { [] } {
				linked[parent] << target
			}
		}
	}
	return linked
}

