			edge: 'tags.articles'
		}
	}
	return n.articles
}

// query_articles starts a query of this row's `articles`. It reads the join
// table `article_tags` first, so it can fail.
pub fn (n TagNode) query_articles() !ArticleQuery {
	pairs := load.link_pairs(n.graph.client.conn, 'article_tags', 'tag_id',
		'article_id', [n.tag.id.str()], .int, .i64)!
	return n.graph.articles().where(load.in_keys('id', pairs.map(it[1]), .i64))
}
